# %%
# Exact copy of set_speed_train_sim_demo.py adapted for Spokane–Lethbridge.
# Changes from original (marked with # SPOKANE):
#   1. Network file
#   2. link_path.csv → spokane_link_path.csv  (generated by spokane_speed_limit_demo.py)
#   3. speed_trace.csv → spokane_speed_trace.csv
#   4. ENABLE_ASSERTS=False (no reference data for Spokane)
#   5. Headless matplotlib backend + save figure to networks/

import time
import polars as pl
import seaborn as sns
import os
import sys
from pathlib import Path

import matplotlib
matplotlib.use("Agg")  # SPOKANE: headless
from altrios.demos import plot_util

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "python"))
import altrios as alt

sns.set_theme()

SHOW_PLOTS = False  # SPOKANE
SAVE_INTERVAL = 1

# SPOKANE: paths
_REPO = Path(__file__).resolve().parents[2]
_NETWORKS = _REPO / "networks"
SPOKANE_NETWORK     = _NETWORKS / "spokane_lethbridge_with_sidings.yaml"
SPOKANE_LINK_PATH   = _NETWORKS / "spokane_link_path.csv"
SPOKANE_SPEED_TRACE = _NETWORKS / "spokane_speed_trace.csv"

for f in [SPOKANE_LINK_PATH, SPOKANE_SPEED_TRACE]:
    if not f.exists():
        raise FileNotFoundError(
            f"Missing: {f}\nRun spokane_speed_limit_demo.py first."
        )

# Build the train config
rail_vehicle_loaded = alt.RailVehicle.from_file(
    alt.resources_root() / "rolling_stock/Manifest_Loaded.yaml"
)
rail_vehicle_empty = alt.RailVehicle.from_file(
    alt.resources_root() / "rolling_stock/Manifest_Empty.yaml"
)

# https://docs.rs/altrios-core/latest/altrios_core/train/struct.TrainConfig.html
train_config = alt.TrainConfig(
    rail_vehicles=[rail_vehicle_loaded, rail_vehicle_empty],
    n_cars_by_type={
        "Manifest_Loaded": 50,
        "Manifest_Empty": 50,
    },
    train_length_meters=None,
    train_mass_kilograms=None,
)

# Build the locomotive consist model
# instantiate battery model
# https://docs.rs/altrios-core/latest/altrios_core/consist/locomotive/powertrain/reversible_energy_storage/struct.ReversibleEnergyStorage.html#
res = alt.ReversibleEnergyStorage.from_file(
    alt.resources_root()
    / "powertrains/reversible_energy_storages/Kokam_NMC_75Ah_flx_drive.yaml"
)
# instantiate electric drivetrain (motors and any gearboxes)
# https://docs.rs/altrios-core/latest/altrios_core/consist/locomotive/powertrain/electric_drivetrain/struct.ElectricDrivetrain.html
edrv = alt.ElectricDrivetrain(
    pwr_out_frac_interp=[0.0, 1.0],
    eta_interp=[0.98, 0.98],
    pwr_out_max_watts=5e9,
    save_interval=SAVE_INTERVAL,
)

loco_type = alt.BatteryElectricLoco.from_pydict(
    {
        "res": res.to_pydict(),
        "edrv": edrv.to_pydict(),
    }
)

bel: alt.Locomotive = alt.Locomotive(
    loco_type=loco_type,
    loco_params=alt.LocoParams.from_dict(
        dict(
            pwr_aux_offset_watts=8.55e3,
            pwr_aux_traction_coeff_ratio=540.0e-6,
            force_max_newtons=667.2e3,
        )
    ),
)
hel: alt.Locomotive = alt.Locomotive.default_hybrid_electric_loco()
# construct a vector of one BEL and several conventional locomotives
loco_vec = [bel] + [alt.Locomotive.default()] * 7 + [hel]
# instantiate consist
loco_con = alt.Consist(
    loco_vec,
    SAVE_INTERVAL,
)

# Instantiate the intermediate `TrainSimBuilder`
tsb = alt.TrainSimBuilder(
    train_id="0",
    train_config=train_config,
    loco_con=loco_con,
)

# Load the network and link path through the network.
network = alt.Network.from_file(SPOKANE_NETWORK)  # SPOKANE
link_path = alt.LinkPath.from_csv_file(SPOKANE_LINK_PATH)  # SPOKANE

# load the prescribed speed trace that the train will follow
speed_trace = alt.SpeedTrace.from_csv_file(SPOKANE_SPEED_TRACE)  # SPOKANE

train_sim: alt.SetSpeedTrainSim = tsb.make_set_speed_train_sim(
    network=network,
    link_path=link_path,
    speed_trace=speed_trace,
    save_interval=SAVE_INTERVAL,
)

train_sim.set_save_interval(SAVE_INTERVAL)
t0 = time.perf_counter()
train_sim.walk()
t1 = time.perf_counter()
print(f"Time to simulate: {t1 - t0:.5g}")

df = train_sim.to_dataframe()

plot_util.plot_locos_from_ts(train_sim, "Distance")

import matplotlib.pyplot as plt
# SPOKANE: save all open figures to disk instead of showing
for i, fig in enumerate(map(plt.figure, plt.get_fignums())):
    fig.savefig(_NETWORKS / f"spokane_set_speed_locos_{i}.png", dpi=150, bbox_inches="tight")
plt.close("all")
print(f"Figures saved to {_NETWORKS}/")

# SPOKANE: skip assertions (no reference data for this route)
# ENABLE_ASSERTS = False
